/* ---------- where the hands and feet go, for every exercise (built in, works offline) ---------- */
const PEGADA = {
  supino_reto_barra: ['Overhand grip, hands about 1.5× shoulder width so your forearms are vertical when the bar touches your chest; thumbs wrapped around the bar, wrists stacked over the forearms. Shoulder blades pinched back and down, feet flat on the floor.', 'Pegada pronada (palmas para os pés), mãos a cerca de 1,5× a largura dos ombros, para os antebraços ficarem na vertical quando a barra toca o peito; polegar envolvendo a barra e punho reto sobre o antebraço. Escápulas juntas e para baixo, pés firmes no chão.', 'Agarre prono, manos a unas 1,5 veces el ancho de hombros para que los antebrazos queden verticales cuando la barra toca el pecho; pulgar rodeando la barra y muñeca recta sobre el antebrazo. Escápulas juntas y abajo, pies firmes en el suelo.'],
  supino_inclinado_barra: ['Bench at 30°. Overhand grip slightly wider than shoulders (about 1.5×), thumbs around the bar, wrists straight. The bar touches the upper chest, just below the collarbones; shoulder blades back and down.', 'Banco a 30°. Pegada pronada um pouco mais larga que os ombros (cerca de 1,5×), polegar envolvendo a barra, punho reto. A barra toca a parte de cima do peito, logo abaixo das clavículas; escápulas para trás e para baixo.', 'Banco a 30°. Agarre prono algo más ancho que los hombros (unas 1,5 veces), pulgar rodeando la barra, muñeca recta. La barra toca la parte alta del pecho, justo bajo las clavículas; escápulas atrás y abajo.'],
  supino_reto_halteres: ['Dumbbells over the chest with palms facing your feet (or turned in up to 45°). At the bottom the dumbbells sit beside the chest, elbows about 45–60° from your body; wrists straight over the elbows.', 'Halteres sobre o peito com as palmas para os pés (ou viradas para dentro até 45°). Embaixo, os halteres ficam ao lado do peito, cotovelos a uns 45–60° do corpo; punho reto em cima do cotovelo.', 'Mancuernas sobre el pecho con las palmas hacia los pies (o giradas hasta 45°). Abajo quedan junto al pecho, codos a unos 45–60° del cuerpo; muñeca recta sobre el codo.'],
  supino_inclinado_halteres: ['Bench at 30°. Palms forward or slightly turned in; lower the dumbbells beside the upper chest with elbows about 45–60° from the body, then press up and slightly in.', 'Banco a 30°. Palmas para a frente ou levemente viradas para dentro; desça os halteres ao lado da parte de cima do peito, cotovelos a uns 45–60° do corpo, e empurre para cima e um pouco para dentro.', 'Banco a 30°. Palmas al frente o algo giradas hacia dentro; baja las mancuernas junto a la parte alta del pecho, codos a unos 45–60° del cuerpo, y empuja hacia arriba y algo hacia dentro.'],
  supino_reto_smith: ['Set the bench so the bar comes down on the middle of your chest. Overhand grip about 1.5× shoulder width, thumbs around the bar, forearms vertical at the bottom.', 'Ajuste o banco para a barra descer no meio do peito. Pegada pronada a cerca de 1,5× a largura dos ombros, polegar envolvendo a barra, antebraços na vertical embaixo.', 'Coloca el banco para que la barra baje a la mitad del pecho. Agarre prono a unas 1,5 veces el ancho de hombros, pulgar rodeando la barra, antebrazos verticales abajo.'],
  supino_inclinado_smith: ['Bench at 30°, placed so the bar comes down just below the collarbones. Overhand grip about 1.5× shoulder width, wrists straight.', 'Banco a 30°, posicionado para a barra descer logo abaixo das clavículas. Pegada pronada a cerca de 1,5× a largura dos ombros, punhos retos.', 'Banco a 30°, colocado para que la barra baje justo bajo las clavículas. Agarre prono a unas 1,5 veces el ancho de hombros, muñecas rectas.'],
  supino_maquina: ['Seat height so the handles line up with the middle of your chest. Grip the handles with wrists straight; keep your back and head on the pad and shoulder blades back.', 'Altura do banco para as pegadas ficarem na linha do meio do peito. Segure com o punho reto; costas e cabeça no encosto e escápulas para trás.', 'Altura del asiento para que los agarres queden a la altura de la mitad del pecho. Agarra con la muñeca recta; espalda y cabeza en el respaldo y escápulas atrás.'],
  crucifixo_halteres: ['Palms facing each other, elbows slightly bent and locked in that angle. Open the arms out to the sides until you feel the chest stretch, about level with the chest, not lower.', 'Palmas viradas uma para a outra, cotovelos levemente dobrados e travados nesse ângulo. Abra os braços para os lados até sentir o peito alongar, mais ou menos na altura do peito, não abaixo.', 'Palmas enfrentadas, codos algo flexionados y fijos en ese ángulo. Abre los brazos a los lados hasta notar el pecho estirado, más o menos a la altura del pecho, no más abajo.'],
  crossover: ['Pulleys set high. One foot forward, slight lean, handles with palms down or facing in. Bring the hands together in a hugging arc in front of the lower chest, elbows slightly bent.', 'Polias no alto. Um pé à frente, tronco levemente inclinado, pegadores com as palmas para baixo ou para dentro. Junte as mãos num arco de "abraço" na frente da parte de baixo do peito, cotovelos levemente dobrados.', 'Poleas altas. Un pie adelante, tronco algo inclinado, agarres con las palmas abajo o hacia dentro. Junta las manos en un arco de "abrazo" frente a la parte baja del pecho, codos algo flexionados.'],
  voador: ['Seat height so the handles are at chest level. Back flat on the pad, elbows slightly bent; bring the handles together in front of the chest without letting the shoulders roll forward.', 'Altura do banco para as pegadas ficarem na altura do peito. Costas apoiadas, cotovelos levemente dobrados; junte as pegadas na frente do peito sem deixar os ombros irem para a frente.', 'Altura del asiento para que los agarres queden a la altura del pecho. Espalda apoyada, codos algo flexionados; junta los agarres frente al pecho sin dejar que los hombros se adelanten.'],
  flexao: ['Hands on the floor slightly wider than shoulders, fingers forward, wrists under the shoulders. Body in one straight line from head to heels, elbows about 45° from the body.', 'Mãos no chão um pouco mais abertas que os ombros, dedos para a frente, punhos embaixo dos ombros. Corpo em linha reta da cabeça aos calcanhares, cotovelos a uns 45° do corpo.', 'Manos en el suelo algo más abiertas que los hombros, dedos al frente, muñecas bajo los hombros. Cuerpo en línea recta de la cabeza a los talones, codos a unos 45° del cuerpo.'],
  mergulho: ['Hands on the bars with palms facing in, wrists straight under the shoulders. Lean the chest a little forward and lower until the upper arms are about parallel to the floor.', 'Mãos nas barras com as palmas viradas para dentro, punhos retos embaixo dos ombros. Incline o peito um pouco para a frente e desça até os braços ficarem mais ou menos paralelos ao chão.', 'Manos en las barras con las palmas hacia dentro, muñecas rectas bajo los hombros. Inclina el pecho un poco hacia delante y baja hasta que los brazos queden más o menos paralelos al suelo.'],
  puxada_frente: ['Overhand grip about 1.5× shoulder width (hands just outside the bend of the bar), thumbs over or around the bar. Thighs locked under the pad, chest up, pull the bar to the upper chest with elbows going down and back.', 'Pegada pronada a cerca de 1,5× a largura dos ombros (mãos logo depois da curva da barra), polegar por cima ou envolvendo. Coxas presas embaixo do apoio, peito aberto, puxe a barra até a parte de cima do peito levando os cotovelos para baixo e para trás.', 'Agarre prono a unas 1,5 veces el ancho de hombros (manos justo fuera de la curva de la barra), pulgar encima o rodeando. Muslos fijos bajo el apoyo, pecho arriba, tira de la barra a la parte alta del pecho llevando los codos abajo y atrás.'],
  puxada_neutra: ['V-handle with palms facing each other, hands close. Lean back slightly and pull the handle to the upper chest, elbows driving down close to your sides.', 'Triângulo com as palmas viradas uma para a outra, mãos próximas. Incline o tronco levemente para trás e puxe até a parte de cima do peito, cotovelos descendo perto do corpo.', 'Triángulo con las palmas enfrentadas, manos juntas. Inclina el tronco un poco atrás y tira hasta la parte alta del pecho, codos bajando pegados al cuerpo.'],
  puxada_unilateral: ['Single handle at the high pulley, palm facing in. Start with the arm fully stretched overhead and pull the elbow down to your side, toward the hip.', 'Pegador único na polia alta, palma virada para dentro. Comece com o braço todo esticado acima da cabeça e puxe o cotovelo para baixo, junto ao corpo, em direção ao quadril.', 'Agarre único en la polea alta, palma hacia dentro. Empieza con el brazo totalmente estirado arriba y tira del codo hacia abajo, junto al cuerpo, hacia la cadera.'],
  barra_fixa: ['Overhand grip a bit wider than shoulders, thumbs around the bar. Start from a dead hang, pull until the chin passes the bar, elbows going down toward your ribs.', 'Pegada pronada um pouco mais larga que os ombros, polegar envolvendo a barra. Comece pendurado com os braços esticados e suba até o queixo passar a barra, levando os cotovelos em direção às costelas.', 'Agarre prono algo más ancho que los hombros, pulgar rodeando la barra. Empieza colgado con los brazos estirados y sube hasta que la barbilla pase la barra, llevando los codos hacia las costillas.'],
  barra_graviton: ['Overhand grip a bit wider than shoulders, knees on the pad. More weight on the stack means more help. Pull until the chin passes the bar.', 'Pegada pronada um pouco mais larga que os ombros, joelhos no apoio. Mais peso na pilha significa mais ajuda. Suba até o queixo passar a barra.', 'Agarre prono algo más ancho que los hombros, rodillas en el apoyo. Más peso en la pila significa más ayuda. Sube hasta que la barbilla pase la barra.'],
  remada_curvada: ['Overhand grip just wider than shoulders. Hinge until the torso is about 30–45° above the floor, knees soft, back flat. Pull the bar to the belly button area, elbows back.', 'Pegada pronada um pouco mais larga que os ombros. Incline o tronco até uns 30–45° acima do chão, joelhos destravados, costas retas. Puxe a barra até a altura do umbigo, cotovelos para trás.', 'Agarre prono algo más ancho que los hombros. Inclina el tronco hasta unos 30–45° sobre el suelo, rodillas flexionadas, espalda recta. Tira de la barra a la altura del ombligo, codos atrás.'],
  serrote: ['Same-side knee and hand on the bench, other foot on the floor, back flat and parallel to the floor. Neutral grip on the dumbbell; pull it toward the hip, elbow close to the body.', 'Joelho e mão do mesmo lado no banco, o outro pé no chão, costas retas e paralelas ao chão. Pegada neutra no halter; puxe em direção ao quadril, cotovelo perto do corpo.', 'Rodilla y mano del mismo lado en el banco, el otro pie en el suelo, espalda recta y paralela al suelo. Agarre neutro; tira hacia la cadera, codo pegado al cuerpo.'],
  remada_apoiada: ['Bench at 30–45°, chest on the pad, feet on the floor. Palms facing each other or down; let the arms hang fully, then pull the elbows back past the torso.', 'Banco a 30–45°, peito no encosto, pés no chão. Palmas viradas uma para a outra ou para baixo; deixe os braços esticarem bem e puxe os cotovelos para trás, passando a linha do tronco.', 'Banco a 30–45°, pecho en el respaldo, pies en el suelo. Palmas enfrentadas o hacia abajo; deja los brazos colgar del todo y tira de los codos atrás pasando el tronco.'],
  remada_baixa: ['Feet on the platform, knees slightly bent, torso upright at the end. V-handle with palms facing each other; pull to the upper belly, chest up, shoulder blades squeezing back.', 'Pés na plataforma, joelhos levemente dobrados, tronco reto no final. Triângulo com as palmas viradas uma para a outra; puxe até a parte de cima da barriga, peito aberto, escápulas apertando para trás.', 'Pies en la plataforma, rodillas algo flexionadas, tronco recto al final. Triángulo con las palmas enfrentadas; tira hasta la parte alta del abdomen, pecho arriba, escápulas apretando atrás.'],
  remada_maquina: ['Seat height so the handles are at the bottom of your chest, chest on the pad. Pull with the elbows going back, squeezing the shoulder blades; let the arms stretch forward between reps.', 'Altura do banco para as pegadas ficarem na parte de baixo do peito, peito no apoio. Puxe levando os cotovelos para trás e apertando as escápulas; deixe os braços esticarem à frente entre as repetições.', 'Altura del asiento para que los agarres queden en la parte baja del pecho, pecho en el apoyo. Tira llevando los codos atrás y apretando las escápulas; deja que los brazos se estiren entre repeticiones.'],
  remada_cavalinho: ['Straddle the bar, close neutral grip on the handle. Hinge to about 45°, back flat, knees soft; pull the handle toward the lower chest, elbows close to the body.', 'Pernas uma de cada lado da barra, pegada neutra e fechada. Incline o tronco a uns 45°, costas retas, joelhos destravados; puxe em direção à parte de baixo do peito, cotovelos perto do corpo.', 'Una pierna a cada lado de la barra, agarre neutro y cerrado. Inclínate a unos 45°, espalda recta, rodillas flexionadas; tira hacia la parte baja del pecho, codos pegados.'],
  pulldown_bracos: ['High pulley, bar or rope, hands about shoulder width. Lean forward slightly, arms almost straight; sweep the hands down in an arc to the thighs.', 'Polia alta, barra ou corda, mãos na largura dos ombros. Incline o tronco levemente, braços quase esticados; leve as mãos num arco até as coxas.', 'Polea alta, barra o cuerda, manos al ancho de hombros. Inclínate un poco, brazos casi rectos; lleva las manos en un arco hasta los muslos.'],
  desenv_halteres: ['Sitting with the back supported (bench at 80–90°). Dumbbells at ear height, palms forward or slightly turned in, forearms vertical; press up and slightly in.', 'Sentado com as costas apoiadas (banco a 80–90°). Halteres na altura das orelhas, palmas para a frente ou levemente para dentro, antebraços na vertical; empurre para cima e um pouco para dentro.', 'Sentado con la espalda apoyada (banco a 80–90°). Mancuernas a la altura de las orejas, palmas al frente o algo hacia dentro, antebrazos verticales; empuja hacia arriba y algo hacia dentro.'],
  desenv_barra: ['Overhand grip just outside the shoulders, forearms vertical, bar resting on the front of the shoulders. Squeeze glutes and abs, press the bar straight up past the face and finish over the middle of the head.', 'Pegada pronada logo por fora dos ombros, antebraços na vertical, barra apoiada na frente dos ombros. Contraia glúteos e abdômen, empurre a barra para cima passando rente ao rosto e termine em cima do meio da cabeça.', 'Agarre prono justo fuera de los hombros, antebrazos verticales, barra apoyada delante de los hombros. Aprieta glúteos y abdomen, empuja la barra hacia arriba rozando la cara y termina sobre el centro de la cabeza.'],
  desenv_smith: ['Bench at 80–90° placed so the bar comes down in front of the face to chin level. Overhand grip just outside the shoulders, forearms vertical.', 'Banco a 80–90°, posicionado para a barra descer na frente do rosto até a altura do queixo. Pegada pronada logo por fora dos ombros, antebraços na vertical.', 'Banco a 80–90°, colocado para que la barra baje delante de la cara hasta la barbilla. Agarre prono justo fuera de los hombros, antebrazos verticales.'],
  desenv_maquina: ['Seat height so the handles start at shoulder level. Back on the pad, wrists straight over the elbows; press up without arching the lower back.', 'Altura do banco para as pegadas começarem na altura dos ombros. Costas no encosto, punho reto em cima do cotovelo; empurre sem arquear a lombar.', 'Altura del asiento para que los agarres empiecen a la altura de los hombros. Espalda en el respaldo, muñeca recta sobre el codo; empuja sin arquear la zona lumbar.'],
  elev_lateral: ['Dumbbells at your sides, palms facing in, elbows slightly bent. Raise the arms out to the sides, slightly forward, until about shoulder height; lead with the elbows.', 'Halteres ao lado do corpo, palmas para dentro, cotovelos levemente dobrados. Levante os braços para os lados, um pouco à frente, até mais ou menos a altura dos ombros; quem lidera são os cotovelos.', 'Mancuernas a los lados, palmas hacia dentro, codos algo flexionados. Sube los brazos a los lados, un poco adelantados, hasta la altura de los hombros; los codos lideran.'],
  elev_lateral_polia: ['Low pulley on the opposite side; the cable crosses in front of your body. Hold the handle, elbow slightly bent, and raise the arm out to the side to shoulder height.', 'Polia baixa do lado oposto; o cabo cruza na frente do corpo. Segure o pegador, cotovelo levemente dobrado, e levante o braço para o lado até a altura do ombro.', 'Polea baja del lado opuesto; el cable cruza por delante del cuerpo. Sujeta el agarre, codo algo flexionado, y sube el brazo al lado hasta la altura del hombro.'],
  elev_lateral_maquina: ['Seat height so your shoulders line up with the machine\'s pivot. Pads on the outside of the arms; raise until the upper arms are about level with the shoulders.', 'Altura do banco para os ombros ficarem alinhados com o eixo da máquina. Apoios por fora dos braços; levante até os braços ficarem mais ou menos na linha dos ombros.', 'Altura del asiento para que los hombros queden alineados con el eje de la máquina. Apoyos por fuera de los brazos; sube hasta que los brazos queden a la altura de los hombros.'],
  crucifixo_inverso: ['Sit facing the pad, handles at shoulder height, palms facing in or down. Open the arms out and back in a wide arc, elbows slightly bent, without shrugging.', 'Sentado de frente para o encosto, pegadas na altura dos ombros, palmas para dentro ou para baixo. Abra os braços para os lados e para trás num arco largo, cotovelos levemente dobrados, sem encolher os ombros.', 'Sentado de cara al respaldo, agarres a la altura de los hombros, palmas hacia dentro o abajo. Abre los brazos atrás en un arco amplio, codos algo flexionados, sin encoger los hombros.'],
  crucifixo_inverso_h: ['Hinge until the torso is nearly parallel to the floor, back flat. Dumbbells hanging, palms facing in; raise them out to the sides in a wide arc, elbows slightly bent.', 'Incline o tronco até quase paralelo ao chão, costas retas. Halteres pendurados, palmas para dentro; levante para os lados num arco largo, cotovelos levemente dobrados.', 'Inclina el tronco casi paralelo al suelo, espalda recta. Mancuernas colgando, palmas hacia dentro; súbelas a los lados en un arco amplio, codos algo flexionados.'],
  face_pull: ['Pulley at face height or a little higher, rope with thumbs pointing back. Pull toward the eyes, elbows high and out, and finish with the hands beside the ears.', 'Polia na altura do rosto ou um pouco acima, corda com os polegares apontando para trás. Puxe em direção aos olhos, cotovelos altos e abertos, e termine com as mãos ao lado das orelhas.', 'Polea a la altura de la cara o algo más alta, cuerda con los pulgares hacia atrás. Tira hacia los ojos, codos altos y abiertos, y termina con las manos junto a las orejas.'],
  rosca_barra: ['Underhand grip at shoulder width (on an EZ bar, the inner angled part). Elbows pinned at your sides; curl without swinging and lower all the way down.', 'Pegada supinada (palmas para cima) na largura dos ombros (na barra W, na parte inclinada de dentro). Cotovelos fixos ao lado do corpo; suba sem balançar e desça até esticar.', 'Agarre supino (palmas arriba) al ancho de hombros (en barra Z, en la parte inclinada interior). Codos fijos a los lados; sube sin balancearte y baja hasta estirar.'],
  rosca_alternada: ['Dumbbells at your sides, palms facing in. As you curl, turn the palm up; elbow stays beside the body. One arm, then the other.', 'Halteres ao lado do corpo, palmas para dentro. Ao subir, gire a palma para cima; o cotovelo fica ao lado do corpo. Um braço de cada vez.', 'Mancuernas a los lados, palmas hacia dentro. Al subir, gira la palma hacia arriba; el codo se queda junto al cuerpo. Un brazo y luego el otro.'],
  rosca_martelo: ['Neutral grip, palms facing each other the whole time (thumbs up). Elbows at your sides; curl to the shoulder and lower all the way.', 'Pegada neutra, palmas viradas uma para a outra o tempo todo (polegar para cima). Cotovelos ao lado do corpo; suba até o ombro e desça até esticar.', 'Agarre neutro, palmas enfrentadas todo el tiempo (pulgar arriba). Codos a los lados; sube hasta el hombro y baja del todo.'],
  rosca_inclinada: ['Bench at 45–60°, back and head on the pad, arms hanging straight down behind the body, palms forward. Curl without moving the upper arm forward.', 'Banco a 45–60°, costas e cabeça apoiadas, braços pendurados retos atrás do corpo, palmas para a frente. Suba sem levar o braço para a frente.', 'Banco a 45–60°, espalda y cabeza apoyadas, brazos colgando rectos detrás del cuerpo, palmas al frente. Sube sin adelantar el brazo.'],
  rosca_scott: ['Seat height so the armpits sit at the top of the pad and the back of the upper arms lies flat on it. Underhand grip at shoulder width; lower until the arms are almost straight.', 'Altura do banco para as axilas ficarem no alto do apoio e a parte de trás dos braços ficar toda apoiada. Pegada supinada na largura dos ombros; desça até os braços ficarem quase esticados.', 'Altura del asiento para que las axilas queden en lo alto del apoyo y la parte trasera de los brazos apoyada. Agarre supino al ancho de hombros; baja hasta casi estirar.'],
  rosca_polia: ['Low pulley, bar or EZ handle, underhand grip at shoulder width. Stand close, elbows at your sides; curl to the shoulders and lower all the way.', 'Polia baixa, barra reta ou W, pegada supinada na largura dos ombros. Fique perto da polia, cotovelos ao lado do corpo; suba até os ombros e desça até esticar.', 'Polea baja, barra recta o Z, agarre supino al ancho de hombros. De pie cerca, codos a los lados; sube a los hombros y baja del todo.'],
  rosca_bayesian: ['Back to a low pulley, one step forward, handle in one hand with the arm behind your body, palm forward. Curl while keeping the elbow behind the torso.', 'De costas para a polia baixa, um passo à frente, pegador numa mão com o braço atrás do corpo, palma para a frente. Suba mantendo o cotovelo atrás do tronco.', 'De espaldas a la polea baja, un paso adelante, agarre en una mano con el brazo detrás del cuerpo, palma al frente. Sube manteniendo el codo detrás del tronco.'],
  triceps_corda: ['High pulley, rope with palms facing each other. Elbows pinned at your sides; push down and spread the rope ends apart at the bottom.', 'Polia alta, corda com as palmas viradas uma para a outra. Cotovelos fixos ao lado do corpo; empurre para baixo e afaste as pontas da corda no final.', 'Polea alta, cuerda con las palmas enfrentadas. Codos fijos a los lados; empuja hacia abajo y separa los extremos de la cuerda al final.'],
  triceps_barra_polia: ['High pulley, straight or V bar, overhand grip about shoulder width. Elbows at your sides; push down until the arms are straight.', 'Polia alta, barra reta ou V, pegada pronada na largura dos ombros. Cotovelos ao lado do corpo; empurre até esticar os braços.', 'Polea alta, barra recta o V, agarre prono al ancho de hombros. Codos a los lados; empuja hasta estirar los brazos.'],
  triceps_overhead: ['Back to the pulley, rope behind your head, one foot forward, slight lean. Elbows beside your head pointing forward; extend the arms forward and up.', 'De costas para a polia, corda atrás da cabeça, um pé à frente, tronco levemente inclinado. Cotovelos ao lado da cabeça apontando para a frente; estique os braços para a frente e para cima.', 'De espaldas a la polea, cuerda detrás de la cabeza, un pie adelante, tronco algo inclinado. Codos junto a la cabeza apuntando al frente; estira los brazos adelante y arriba.'],
  triceps_frances: ['One dumbbell held with both hands under the top plate, arms overhead. Elbows close to the head, pointing up; lower behind the head and extend.', 'Um halter seguro com as duas mãos por baixo do disco de cima, braços acima da cabeça. Cotovelos perto da cabeça, apontando para cima; desça atrás da cabeça e estique.', 'Una mancuerna sujeta con las dos manos bajo el disco superior, brazos sobre la cabeza. Codos cerca de la cabeza, apuntando arriba; baja detrás de la cabeza y estira.'],
  triceps_testa: ['Lying on the bench, EZ bar with a narrow overhand grip (inner bends). Upper arms tilted slightly back toward the head; bend only the elbows, lowering to the forehead or just behind the head.', 'Deitado no banco, barra W com pegada pronada fechada (curvas de dentro). Braços levemente inclinados para trás, em direção à cabeça; dobre só os cotovelos, descendo até a testa ou logo atrás da cabeça.', 'Tumbado en el banco, barra Z con agarre prono cerrado (curvas interiores). Brazos algo inclinados hacia la cabeza; flexiona solo los codos, bajando a la frente o justo detrás de la cabeza.'],
  supino_fechado: ['Overhand grip about shoulder width (not narrower, to spare the wrists). Elbows close to the body; touch the bar to the lower chest.', 'Pegada pronada na largura dos ombros (não mais fechada, para poupar os punhos). Cotovelos perto do corpo; encoste a barra na parte de baixo do peito.', 'Agarre prono al ancho de hombros (no más cerrado, para cuidar las muñecas). Codos pegados al cuerpo; toca la parte baja del pecho.'],
  agachamento: ['Bar on the upper back (on the traps, not the neck), hands just outside the shoulders, elbows pointing down. Feet shoulder-width apart, toes out 15–30°; knees follow the toes, go down at least until the thighs are parallel.', 'Barra no alto das costas (no trapézio, não no pescoço), mãos logo por fora dos ombros, cotovelos apontando para baixo. Pés na largura dos ombros, pontas para fora 15–30°; joelhos seguem a ponta dos pés, desça pelo menos até as coxas ficarem paralelas ao chão.', 'Barra en la parte alta de la espalda (en el trapecio, no en el cuello), manos justo fuera de los hombros, codos hacia abajo. Pies al ancho de hombros, puntas fuera 15–30°; rodillas siguen las puntas, baja al menos hasta que los muslos queden paralelos.'],
  agachamento_smith: ['Bar on the upper back, hands just outside the shoulders. Feet slightly in front of the bar, shoulder-width, toes out a little; sit down between the heels, knees following the toes.', 'Barra no alto das costas, mãos logo por fora dos ombros. Pés um pouco à frente da barra, na largura dos ombros, pontas levemente para fora; sente entre os calcanhares, joelhos acompanhando a ponta dos pés.', 'Barra en la parte alta de la espalda, manos justo fuera de los hombros. Pies algo por delante de la barra, al ancho de hombros, puntas algo fuera; siéntate entre los talones, rodillas siguiendo las puntas.'],
  hack: ['Back and shoulders against the pads, feet shoulder-width in the middle of the platform. Go down as deep as you can with the heels flat and the lower back on the pad.', 'Costas e ombros no encosto, pés na largura dos ombros no meio da plataforma. Desça o mais fundo que conseguir com os calcanhares no chão e a lombar no encosto.', 'Espalda y hombros en los apoyos, pies al ancho de hombros en el centro de la plataforma. Baja lo más profundo posible con los talones apoyados y la zona lumbar en el respaldo.'],
  pendulo: ['Back on the pad, shoulders under the pads, feet shoulder-width in the middle of the platform. Go deep with control; knees travel forward over the toes.', 'Costas no encosto, ombros embaixo dos apoios, pés na largura dos ombros no meio da plataforma. Desça fundo com controle; os joelhos avançam por cima da ponta dos pés.', 'Espalda en el respaldo, hombros bajo los apoyos, pies al ancho de hombros en el centro de la plataforma. Baja profundo con control; las rodillas avanzan sobre las puntas.'],
  leg_press: ['Feet shoulder-width in the middle of the platform (higher works glutes more, lower works quads more). Lower until the knees reach about 90° or deeper while the lower back stays on the seat.', 'Pés na largura dos ombros no meio da plataforma (mais alto trabalha mais glúteo, mais baixo mais quadríceps). Desça até os joelhos chegarem a uns 90° ou mais, sem a lombar sair do encosto.', 'Pies al ancho de hombros en el centro de la plataforma (más arriba trabaja más glúteo, más abajo más cuádriceps). Baja hasta unos 90° de rodilla o más, sin despegar la zona lumbar.'],
  leg_horizontal: ['Feet shoulder-width in the middle of the platform, back flat on the seat. Bend the knees toward the chest and push back without locking the knees hard.', 'Pés na largura dos ombros no meio da plataforma, costas apoiadas. Traga os joelhos em direção ao peito e empurre de volta sem travar os joelhos com força.', 'Pies al ancho de hombros en el centro de la plataforma, espalda apoyada. Lleva las rodillas hacia el pecho y empuja de vuelta sin bloquear fuerte las rodillas.'],
  bulgaro: ['Rear foot laces-down on a bench, front foot far enough forward that at the bottom the front shin is roughly vertical or slightly forward. Dumbbells at your sides; go down until the back knee nearly touches the floor.', 'Peito do pé de trás apoiado no banco, pé da frente longe o bastante para, embaixo, a canela da frente ficar quase na vertical ou levemente à frente. Halteres ao lado do corpo; desça até o joelho de trás quase encostar no chão.', 'Empeine del pie trasero en el banco, pie delantero lo bastante adelante para que abajo la espinilla quede casi vertical o algo adelantada. Mancuernas a los lados; baja hasta que la rodilla trasera casi toque el suelo.'],
  afundo: ['Long stance, feet hip-width apart (not on one line). Dumbbells at your sides; drop the back knee toward the floor, front knee over the middle of the foot.', 'Passada longa, pés afastados na largura do quadril (não na mesma linha). Halteres ao lado do corpo; desça o joelho de trás em direção ao chão, joelho da frente em cima do meio do pé.', 'Zancada larga, pies separados al ancho de cadera (no en la misma línea). Mancuernas a los lados; baja la rodilla trasera hacia el suelo, rodilla delantera sobre el centro del pie.'],
  goblet: ['Hold one dumbbell vertically against the chest by the top plate, elbows down. Feet a little wider than shoulders, toes out; sit down between the knees with the chest up.', 'Segure um halter na vertical junto ao peito pelo disco de cima, cotovelos para baixo. Pés um pouco mais abertos que os ombros, pontas para fora; sente entre os joelhos com o peito aberto.', 'Sujeta una mancuerna vertical contra el pecho por el disco superior, codos abajo. Pies algo más abiertos que los hombros, puntas fuera; siéntate entre las rodillas con el pecho arriba.'],
  extensora: ['Back on the pad, knee joint lined up with the machine\'s pivot, shin pad just above the ankle. Hold the handles; straighten the legs fully and lower slowly.', 'Costas no encosto, joelho alinhado com o eixo da máquina, apoio da canela logo acima do tornozelo. Segure as pegadas; estique as pernas por completo e desça devagar.', 'Espalda en el respaldo, rodilla alineada con el eje de la máquina, apoyo justo encima del tobillo. Sujeta los agarres; estira las piernas del todo y baja despacio.'],
  step_up: ['Box about knee height. Whole foot on the box; push through the heel of the top leg, using the back leg as little as possible.', 'Caixa mais ou menos na altura do joelho. Pé inteiro em cima; empurre pelo calcanhar da perna de cima, usando o mínimo possível a perna de trás.', 'Cajón más o menos a la altura de la rodilla. Pie entero encima; empuja con el talón de la pierna de arriba, usando lo mínimo la pierna de atrás.'],
  stiff: ['Overhand grip just outside the thighs. Knees soft and fixed; push the hips back, keep the bar against the legs and the back flat, and lower until you feel a strong hamstring stretch (usually mid-shin).', 'Pegada pronada logo por fora das coxas. Joelhos destravados e fixos; leve o quadril para trás, barra raspando nas pernas e costas retas, e desça até sentir o posterior alongar bem (normalmente no meio da canela).', 'Agarre prono justo fuera de los muslos. Rodillas algo flexionadas y fijas; lleva la cadera atrás, barra rozando las piernas y espalda recta, y baja hasta notar un buen estiramiento (normalmente a mitad de la espinilla).'],
  stiff_unilateral: ['Stand on one leg, knee soft; dumbbell in the opposite hand. Tip forward from the hip while the free leg goes back in line with the torso, hips square to the floor.', 'Apoie numa perna, joelho destravado; halter na mão oposta. Incline o tronco a partir do quadril enquanto a perna livre vai para trás alinhada com o tronco, quadril reto em relação ao chão.', 'Apoya una pierna, rodilla algo flexionada; mancuerna en la mano contraria. Inclínate desde la cadera mientras la pierna libre va atrás alineada con el tronco, cadera recta respecto al suelo.'],
  terra: ['Feet hip-width, bar over the middle of the foot. Overhand or mixed grip just outside the knees; shins touch the bar, back flat, chest up. Push the floor away and stand up tall, bar close to the legs.', 'Pés na largura do quadril, barra em cima do meio do pé. Pegada pronada ou mista logo por fora dos joelhos; canelas encostadas na barra, costas retas, peito aberto. Empurre o chão e fique em pé, barra junto às pernas.', 'Pies al ancho de cadera, barra sobre el centro del pie. Agarre prono o mixto justo fuera de las rodillas; espinillas tocando la barra, espalda recta, pecho arriba. Empuja el suelo y ponte de pie, barra pegada a las piernas.'],
  mesa_flexora: ['Lying face down, knees just off the bench edge, pad on the back of the ankles. Hold the handles; curl the heels toward the glutes without lifting the hips.', 'Deitado de bruços, joelhos logo depois da borda do banco, apoio atrás dos tornozelos. Segure as pegadas; traga os calcanhares em direção aos glúteos sem levantar o quadril.', 'Tumbado boca abajo, rodillas justo fuera del borde, apoyo detrás de los tobillos. Sujeta los agarres; lleva los talones hacia los glúteos sin levantar la cadera.'],
  cadeira_flexora: ['Knees lined up with the machine\'s pivot, thigh pad snug above the knees, roller behind the ankles. Lean slightly forward and curl the legs all the way under the seat.', 'Joelhos alinhados com o eixo da máquina, apoio das coxas firme acima dos joelhos, rolo atrás dos tornozelos. Incline o tronco levemente à frente e dobre as pernas até o fim, embaixo do banco.', 'Rodillas alineadas con el eje de la máquina, apoyo de muslos firme sobre las rodillas, rodillo detrás de los tobillos. Inclínate un poco adelante y flexiona las piernas del todo bajo el asiento.'],
  hiperextensao: ['Hip pad just below the hip bones so you can bend at the hip, feet locked under the roller. Arms crossed on the chest; lower with a flat back and come up until the body is in a straight line.', 'Apoio do quadril logo abaixo do osso do quadril, para você conseguir dobrar no quadril, pés presos embaixo do rolo. Braços cruzados no peito; desça com as costas retas e suba até o corpo ficar em linha reta.', 'Apoyo de cadera justo bajo los huesos de la cadera para poder flexionar ahí, pies fijos bajo el rodillo. Brazos cruzados en el pecho; baja con la espalda recta y sube hasta quedar en línea recta.'],
  hip_thrust: ['Upper back (just below the shoulder blades) on the bench edge, bar padded over the hip crease, hands holding it outside the hips. Feet hip-width so the shins are vertical at the top; chin tucked.', 'Parte de cima das costas (logo abaixo das escápulas) na borda do banco, barra com proteção na dobra do quadril, mãos segurando por fora do quadril. Pés na largura do quadril, de forma que no alto as canelas fiquem na vertical; queixo recolhido.', 'Parte alta de la espalda (justo bajo las escápulas) en el borde del banco, barra con protección en el pliegue de la cadera, manos sujetándola fuera de la cadera. Pies al ancho de cadera para que arriba las espinillas queden verticales; barbilla recogida.'],
  hip_thrust_smith: ['Upper back on the bench edge, Smith bar padded over the hip crease. Feet hip-width, shins vertical at the top; push through the heels and squeeze the glutes at the top.', 'Parte de cima das costas na borda do banco, barra do Smith com proteção na dobra do quadril. Pés na largura do quadril, canelas na vertical no alto; empurre pelos calcanhares e contraia os glúteos no topo.', 'Parte alta de la espalda en el borde del banco, barra del Smith con protección en el pliegue de la cadera. Pies al ancho de cadera, espinillas verticales arriba; empuja con los talones y aprieta los glúteos arriba.'],
  hip_thrust_maq: ['Upper back on the pad, belt or pad across the hips, feet hip-width so the shins are vertical at the top. Push through the heels; pause with the glutes squeezed.', 'Parte de cima das costas no apoio, cinto ou apoio sobre o quadril, pés na largura do quadril para as canelas ficarem na vertical no alto. Empurre pelos calcanhares; pause com os glúteos contraídos.', 'Parte alta de la espalda en el apoyo, cinturón o apoyo sobre la cadera, pies al ancho de cadera para que las espinillas queden verticales arriba. Empuja con los talones; pausa apretando los glúteos.'],
  coice_polia: ['Ankle strap on a low pulley, hands on the frame, slight forward lean. Kick the leg back, knee slightly bent, without arching the lower back.', 'Tornozeleira na polia baixa, mãos na estrutura, tronco levemente inclinado. Leve a perna para trás, joelho levemente dobrado, sem arquear a lombar.', 'Tobillera en la polea baja, manos en la estructura, tronco algo inclinado. Lleva la pierna atrás, rodilla algo flexionada, sin arquear la zona lumbar.'],
  gluteo_maquina: ['Chest or forearms on the pads, foot on the plate. Push the leg back and up until the hip is fully extended, without arching the lower back.', 'Peito ou antebraços nos apoios, pé na plataforma. Empurre a perna para trás e para cima até estender o quadril, sem arquear a lombar.', 'Pecho o antebrazos en los apoyos, pie en la plataforma. Empuja la pierna atrás y arriba hasta extender la cadera, sin arquear la zona lumbar.'],
  abdutora: ['Back on the pad, pads on the outside of the knees. Push the knees apart as far as you can and return slowly; leaning slightly forward hits the glutes more.', 'Costas no encosto, apoios por fora dos joelhos. Afaste os joelhos o máximo que conseguir e volte devagar; inclinar o tronco levemente à frente pega mais o glúteo.', 'Espalda en el respaldo, apoyos por fuera de las rodillas. Separa las rodillas todo lo que puedas y vuelve despacio; inclinarte algo adelante trabaja más el glúteo.'],
  ponte_gluteo: ['Lying on your back, knees bent, feet hip-width close to the glutes, arms on the floor. Push through the heels and lift the hips until the body is straight from knees to shoulders.', 'Deitado de costas, joelhos dobrados, pés na largura do quadril perto dos glúteos, braços no chão. Empurre pelos calcanhares e suba o quadril até o corpo ficar reto dos joelhos aos ombros.', 'Tumbado boca arriba, rodillas flexionadas, pies al ancho de cadera cerca de los glúteos, brazos en el suelo. Empuja con los talones y sube la cadera hasta quedar recto de rodillas a hombros.'],
  coice_caneleira: ['On all fours, hands under shoulders, knees under hips, ankle weight on. Kick one leg back and up with the knee bent at 90°, without arching the lower back.', 'De quatro apoios, mãos embaixo dos ombros, joelhos embaixo do quadril, caneleira no tornozelo. Leve uma perna para trás e para cima com o joelho dobrado a 90°, sem arquear a lombar.', 'A cuatro patas, manos bajo los hombros, rodillas bajo la cadera, tobillera puesta. Lleva una pierna atrás y arriba con la rodilla a 90°, sin arquear la zona lumbar.'],
  agach_sumo: ['Wide stance, toes out 30–45°. Hold one dumbbell by the top plate hanging between the legs; sit straight down with the knees pushed out over the toes.', 'Base larga, pontas dos pés para fora 30–45°. Segure um halter pelo disco de cima, pendurado entre as pernas; desça reto com os joelhos abertos na direção da ponta dos pés.', 'Postura amplia, puntas fuera 30–45°. Sujeta una mancuerna por el disco superior colgando entre las piernas; baja recto con las rodillas abiertas hacia las puntas.'],
  abducao_elastico: ['Mini band just above the knees. Sitting at the edge of a bench with feet hip-width, push the knees apart against the band and return slowly.', 'Mini band logo acima dos joelhos. Sentado na ponta do banco com os pés na largura do quadril, afaste os joelhos contra o elástico e volte devagar.', 'Mini banda justo encima de las rodillas. Sentado en el borde del banco con los pies al ancho de cadera, separa las rodillas contra la banda y vuelve despacio.'],
  adutora: ['Back on the pad, pads on the inside of the knees, starting as wide as is comfortable. Squeeze the knees together and open slowly.', 'Costas no encosto, apoios por dentro dos joelhos, começando tão aberto quanto for confortável. Feche os joelhos e abra devagar.', 'Espalda en el respaldo, apoyos por dentro de las rodillas, empezando tan abierto como sea cómodo. Junta las rodillas y abre despacio.'],
  pant_pe: ['Balls of the feet on the edge of the step, shoulders under the pads, knees straight but not locked. Drop the heels as low as you can, pause, then rise as high as possible.', 'Ponta dos pés na borda do degrau, ombros embaixo dos apoios, joelhos esticados sem travar. Desça os calcanhares o máximo possível, pause e suba o mais alto que conseguir.', 'Puntas de los pies en el borde del escalón, hombros bajo los apoyos, rodillas rectas sin bloquear. Baja los talones todo lo posible, pausa y sube lo más alto que puedas.'],
  pant_sentado: ['Balls of the feet on the plate, pad snug on the lower thighs just above the knees. Drop the heels low, pause, and rise all the way up.', 'Ponta dos pés na plataforma, apoio firme na parte de baixo das coxas, logo acima dos joelhos. Desça bem os calcanhares, pause e suba até o fim.', 'Puntas de los pies en la plataforma, apoyo firme en la parte baja de los muslos, justo sobre las rodillas. Baja bien los talones, pausa y sube del todo.'],
  pant_leg: ['In the leg press with legs almost straight, balls of the feet on the bottom edge of the platform. Let the toes come toward you for a full stretch, then push with the toes.', 'No leg press com as pernas quase esticadas, ponta dos pés na borda de baixo da plataforma. Deixe a ponta dos pés vir em sua direção para alongar bem e depois empurre com a ponta dos pés.', 'En la prensa con las piernas casi rectas, puntas de los pies en el borde inferior de la plataforma. Deja que las puntas vengan hacia ti para estirar bien y luego empuja con las puntas.'],
  pant_smith: ['Bar on the upper back, balls of the feet on a step or plate under the bar. Drop the heels low, pause, rise as high as possible.', 'Barra no alto das costas, ponta dos pés num degrau ou anilha embaixo da barra. Desça bem os calcanhares, pause e suba o mais alto possível.', 'Barra en la parte alta de la espalda, puntas de los pies en un escalón o disco bajo la barra. Baja bien los talones, pausa y sube lo más alto posible.'],
  pant_unilateral: ['One foot\'s ball on the edge of a step, the other foot behind the ankle, one hand on a support. Drop the heel low, pause, rise as high as possible.', 'Ponta de um pé na borda do degrau, o outro pé atrás do tornozelo, uma mão num apoio. Desça o calcanhar bem, pause e suba o mais alto possível.', 'Punta de un pie en el borde del escalón, el otro pie detrás del tobillo, una mano en un apoyo. Baja bien el talón, pausa y sube lo más alto posible.'],
  prancha: ['Forearms on the floor, elbows under the shoulders, body in a straight line from head to heels. Squeeze glutes and abs, and breathe normally.', 'Antebraços no chão, cotovelos embaixo dos ombros, corpo em linha reta da cabeça aos calcanhares. Contraia glúteos e abdômen e respire normalmente.', 'Antebrazos en el suelo, codos bajo los hombros, cuerpo en línea recta de la cabeza a los talones. Aprieta glúteos y abdomen y respira normal.'],
  prancha_lateral: ['On one forearm, elbow under the shoulder, feet stacked. Lift the hips so the body is straight from head to feet; don\'t let the hips sag.', 'Apoiado num antebraço, cotovelo embaixo do ombro, pés um em cima do outro. Suba o quadril até o corpo ficar reto da cabeça aos pés; não deixe o quadril cair.', 'Apoyado en un antebrazo, codo bajo el hombro, pies uno sobre otro. Sube la cadera hasta quedar recto de la cabeza a los pies; no dejes caer la cadera.'],
  abd_polia: ['Kneeling facing a high pulley, rope held beside the head. Keep the hips still and curl the ribs toward the pelvis, bringing the elbows toward the knees.', 'Ajoelhado de frente para a polia alta, corda segura ao lado da cabeça. Mantenha o quadril parado e enrole as costelas em direção à pelve, levando os cotovelos em direção aos joelhos.', 'De rodillas frente a la polea alta, cuerda junto a la cabeza. Mantén la cadera quieta y enrolla las costillas hacia la pelvis, llevando los codos hacia las rodillas.'],
  elev_pernas: ['Hang from the bar with an overhand grip at shoulder width. Without swinging, raise the knees (or straight legs) by curling the pelvis up.', 'Pendurado na barra com pegada pronada na largura dos ombros. Sem balançar, suba os joelhos (ou as pernas esticadas) enrolando a pelve para cima.', 'Colgado de la barra con agarre prono al ancho de hombros. Sin balancearte, sube las rodillas (o las piernas rectas) enrollando la pelvis hacia arriba.'],
  abd_supra: ['Lying on your back, knees bent, feet on the floor, hands on the chest or beside the head (not pulling the neck). Curl the shoulder blades off the floor.', 'Deitado de costas, joelhos dobrados, pés no chão, mãos no peito ou ao lado da cabeça (sem puxar o pescoço). Enrole o tronco até tirar as escápulas do chão.', 'Tumbado boca arriba, rodillas flexionadas, pies en el suelo, manos en el pecho o junto a la cabeza (sin tirar del cuello). Enrolla hasta despegar las escápulas.'],
  elev_pernas_solo: ['Lying on your back, hands under the glutes or beside the hips, lower back pressed to the floor. Raise straight legs to vertical and lower slowly without arching.', 'Deitado de costas, mãos embaixo dos glúteos ou ao lado do quadril, lombar colada no chão. Suba as pernas esticadas até a vertical e desça devagar sem arquear.', 'Tumbado boca arriba, manos bajo los glúteos o junto a la cadera, zona lumbar pegada al suelo. Sube las piernas rectas hasta la vertical y baja despacio sin arquear.'],
  pallof: ['Stand side-on to a pulley at chest height, handle with both hands at the chest, feet shoulder-width. Press the hands straight forward and hold without letting the body rotate.', 'Fique de lado para a polia na altura do peito, pegador com as duas mãos junto ao peito, pés na largura dos ombros. Empurre as mãos reto para a frente e segure sem deixar o corpo girar.', 'De lado a la polea a la altura del pecho, agarre con las dos manos en el pecho, pies al ancho de hombros. Empuja las manos al frente y aguanta sin dejar que el cuerpo gire.'],
};
/* home versions (training at home today) */
Object.assign(PEGADA, {
  flexao_inclinada: ['Hands on the edge of a sturdy table, or of a chair pushed against a wall, a little wider than the shoulders. Body straight from head to heels; lower the chest to the edge with the elbows about 45° from the body, then push away. The higher the support, the easier.', 'Mãos na borda de uma mesa firme, ou de uma cadeira encostada na parede, um pouco mais abertas que os ombros. Corpo reto da cabeça aos calcanhares; desça o peito até a borda com os cotovelos a uns 45° do corpo e empurre. Quanto mais alto o apoio, mais fácil.', 'Manos en el borde de una mesa firme, o de una silla apoyada contra la pared, un poco más abiertas que los hombros. Cuerpo recto de la cabeza a los talones; baja el pecho hasta el borde con los codos a unos 45° del cuerpo y empuja. Cuanto más alto el apoyo, más fácil.'],
  flexao_declinada: ['Feet on a sturdy chair or bench, hands on the floor a little wider than the shoulders. Body straight and abs tight; lower until the nose nearly touches the floor, elbows about 45° from the body. It works more of the upper chest and shoulders.', 'Pés numa cadeira firme ou banco, mãos no chão um pouco mais abertas que os ombros. Corpo reto e abdômen firme; desça até o nariz quase tocar o chão, cotovelos a uns 45° do corpo. Trabalha mais a parte de cima do peito e os ombros.', 'Pies en una silla firme o banco, manos en el suelo un poco más abiertas que los hombros. Cuerpo recto y abdomen firme; baja hasta que la nariz casi toque el suelo, codos a unos 45° del cuerpo. Trabaja más la parte alta del pecho y los hombros.'],
  flexao_diamante: ['Hands together under the chest, thumbs and index fingers making a diamond. Body straight; lower the chest to the hands with the elbows close to the body, then push up. Knees on the floor if needed.', 'Mãos juntas embaixo do peito, polegares e indicadores formando um losango. Corpo reto; desça o peito até as mãos com os cotovelos perto do corpo e suba. Se precisar, apoie os joelhos no chão.', 'Manos juntas bajo el pecho, pulgares e índices formando un rombo. Cuerpo recto; baja el pecho hasta las manos con los codos pegados al cuerpo y sube. Si hace falta, apoya las rodillas.'],
  flexao_pike: ['Start in a push-up, walk the feet in and lift the hips high, making an upside-down V. Hands at shoulder width; bend the elbows to bring the top of the head toward the floor a little in front of the hands, then press back up.', 'Comece na posição de flexão, aproxime os pés e suba o quadril, formando um V de cabeça para baixo. Mãos na largura dos ombros; dobre os cotovelos levando o topo da cabeça em direção ao chão, um pouco à frente das mãos, e empurre de volta.', 'Empieza en posición de flexión, acerca los pies y sube la cadera formando una V invertida. Manos al ancho de los hombros; dobla los codos llevando la coronilla hacia el suelo, un poco por delante de las manos, y empuja de vuelta.'],
  supino_chao: ['Lie on the floor with the knees bent, a dumbbell in each hand over the chest. Lower until the backs of the upper arms touch the floor (elbows about 45° from the body), pause a moment, then press up. The floor limits the range, which is easy on the shoulders.', 'Deitado no chão com os joelhos dobrados, um halter em cada mão sobre o peito. Desça até a parte de trás dos braços encostar no chão (cotovelos a uns 45° do corpo), pare um instante e empurre. O chão limita o movimento, o que poupa os ombros.', 'Tumbado en el suelo con las rodillas dobladas, una mancuerna en cada mano sobre el pecho. Baja hasta que la parte de atrás de los brazos toque el suelo (codos a unos 45° del cuerpo), pausa un instante y empuja. El suelo limita el recorrido y cuida los hombros.'],
  mergulho_cadeira: ['Hands on the front edge of a sturdy chair pushed against a wall, fingers forward, hips just in front of the seat. Bend the elbows straight back to about 90°, then push up. Knees bent is easier; legs straight is harder.', 'Mãos na borda da frente de uma cadeira firme encostada na parede, dedos para a frente, quadril logo à frente do assento. Dobre os cotovelos para trás até uns 90° e empurre para subir. Joelhos dobrados é mais fácil; pernas esticadas, mais difícil.', 'Manos en el borde delantero de una silla firme apoyada contra la pared, dedos hacia delante, cadera justo delante del asiento. Dobla los codos hacia atrás hasta unos 90° y empuja para subir. Rodillas dobladas es más fácil; piernas estiradas, más difícil.'],
  remada_invertida: ['Lie under a sturdy table that cannot tip and hold the edge with the hands at shoulder width. Body straight from heels to head (knees bent makes it easier); pull the chest to the edge squeezing the shoulder blades, then lower slowly. Test the table before the first rep.', 'Deite embaixo de uma mesa firme, que não vire, e segure na borda com as mãos na largura dos ombros. Corpo reto dos calcanhares à cabeça (joelhos dobrados facilitam); puxe o peito até a borda juntando as escápulas e desça devagar. Teste a mesa antes da primeira repetição.', 'Túmbate bajo una mesa firme que no pueda volcar y agarra el borde con las manos al ancho de los hombros. Cuerpo recto de los talones a la cabeza (con las rodillas dobladas es más fácil); tira del pecho hacia el borde juntando las escápulas y baja despacio. Prueba la mesa antes de la primera repetición.'],
  remada_mochila: ['Hold a loaded backpack by the top handle or by both straps. Hinge at the hips until the torso is at about 45°, back flat, knees soft. Pull the backpack to the lower ribs leading with the elbows, squeeze the shoulder blades and lower slowly.', 'Segure a mochila com peso pela alça de cima ou pelas duas alças. Incline o tronco a uns 45° dobrando o quadril, costas retas, joelhos levemente dobrados. Puxe a mochila até as costelas de baixo levando os cotovelos para trás, junte as escápulas e desça devagar.', 'Sujeta la mochila con peso por el asa de arriba o por las dos correas. Inclina el tronco a unos 45° doblando la cadera, espalda recta, rodillas un poco dobladas. Tira de la mochila hacia las costillas bajas llevando los codos atrás, junta las escápulas y baja despacio.'],
  remada_halteres: ['A dumbbell in each hand, palms facing each other. Hinge at the hips until the torso is at about 45°, back flat, knees soft. Pull the dumbbells to the sides of the waist, elbows close to the body, then lower slowly.', 'Um halter em cada mão, palmas viradas uma para a outra. Incline o tronco a uns 45° dobrando o quadril, costas retas, joelhos levemente dobrados. Puxe os halteres até a lateral da cintura, cotovelos perto do corpo, e desça devagar.', 'Una mancuerna en cada mano, palmas enfrentadas. Inclina el tronco a unos 45° doblando la cadera, espalda recta, rodillas un poco dobladas. Tira de las mancuernas hacia los lados de la cintura, codos cerca del cuerpo, y baja despacio.'],
  remada_elastico: ['Sit with the legs straight and the band around the soles of the feet (or anchored at chest height), one end in each hand. Sit tall and pull the hands to the waist, elbows back close to the body, squeezing the shoulder blades.', 'Sentado com as pernas esticadas e o elástico passando pela sola dos pés (ou preso na altura do peito), uma ponta em cada mão. Coluna alta; puxe as mãos até a cintura, cotovelos para trás perto do corpo, juntando as escápulas.', 'Sentado con las piernas estiradas y la banda alrededor de las plantas de los pies (o anclada a la altura del pecho), un extremo en cada mano. Espalda alta; tira de las manos hacia la cintura, codos atrás cerca del cuerpo, juntando las escápulas.'],
  puxada_elastico: ['Anchor the band high on something solid (a door anchor closed on the hinge side, or a pull-up bar). Kneel or sit facing it with the arms up. Pull the elbows down to your sides, bringing the hands to the upper chest, then let them rise slowly.', 'Prenda o elástico no alto em algo firme (uma âncora de porta fechada do lado da dobradiça, ou uma barra fixa). Ajoelhado ou sentado de frente, braços para cima. Puxe os cotovelos para baixo até o lado do corpo, levando as mãos ao alto do peito, e deixe subir devagar.', 'Ancla la banda arriba en algo firme (un anclaje de puerta cerrado del lado de las bisagras, o una barra). De rodillas o sentado de frente, brazos arriba. Tira de los codos hacia abajo hasta los costados, llevando las manos a la parte alta del pecho, y deja subir despacio.'],
  barra_supinada: ['Underhand grip (palms facing you) at shoulder width. Hang with straight arms, pull until the chin passes the bar with the elbows coming down in front of the body, then lower all the way. Only on a bar that is firmly fixed.', 'Pegada supinada (palmas viradas para você) na largura dos ombros. Pendurado com os braços esticados, puxe até o queixo passar da barra, cotovelos descendo na frente do corpo, e desça até esticar. Só numa barra bem fixada.', 'Agarre supino (palmas hacia ti) al ancho de los hombros. Colgado con los brazos estirados, tira hasta que la barbilla pase la barra, con los codos bajando delante del cuerpo, y baja hasta estirar. Solo en una barra bien fijada.'],
  ytw: ['Lie face down (or hinge forward standing), thumbs up. Raise the arms in a Y overhead, then a T out to the sides, then pull the elbows down and back into a W, squeezing the shoulder blades each time. Slowly, holding 1–2 s at the top.', 'Deitado de barriga para baixo (ou em pé com o tronco inclinado), polegares para cima. Suba os braços em Y acima da cabeça, depois em T para os lados, e puxe os cotovelos para baixo e para trás em W, juntando as escápulas a cada vez. Devagar, segurando 1–2 s em cima.', 'Tumbado boca abajo (o de pie con el tronco inclinado), pulgares hacia arriba. Sube los brazos en Y sobre la cabeza, luego en T hacia los lados, y lleva los codos abajo y atrás en W, juntando las escápulas cada vez. Despacio, aguantando 1–2 s arriba.'],
  superman: ['Face down with the arms stretched forward. Squeeze the glutes and lift the arms, chest and legs a few centimetres off the floor, looking at the floor; hold 2 s and lower slowly. A small range, with no jerking.', 'De barriga para baixo, braços esticados para a frente. Contraia os glúteos e tire braços, peito e pernas alguns centímetros do chão, olhando para o chão; segure 2 s e desça devagar. Movimento pequeno, sem tranco.', 'Boca abajo, brazos estirados hacia delante. Aprieta los glúteos y levanta brazos, pecho y piernas unos centímetros del suelo, mirando al suelo; aguanta 2 s y baja despacio. Recorrido corto, sin tirones.'],
  rosca_mochila: ['Hold a loaded backpack by the top handle, or by both straps, palms up and elbows at your sides. Curl it up without swinging the body, squeeze, and lower slowly until the arms are straight.', 'Segure a mochila com peso pela alça de cima, ou pelas duas alças, palmas para cima e cotovelos junto ao corpo. Suba sem balançar o corpo, contraia e desça devagar até esticar os braços.', 'Sujeta la mochila con peso por el asa de arriba, o por las dos correas, palmas hacia arriba y codos pegados al cuerpo. Sube sin balancear el cuerpo, aprieta y baja despacio hasta estirar los brazos.'],
  rosca_elastico: ['Stand on the middle of the band, feet hip-width, one end in each hand, palms forward. Elbows fixed at your sides; curl the hands to the shoulders and lower slowly against the band.', 'Pise no meio do elástico, pés na largura do quadril, uma ponta em cada mão, palmas para a frente. Cotovelos parados junto ao corpo; suba as mãos até os ombros e desça devagar segurando o elástico.', 'Pisa el centro de la banda, pies al ancho de cadera, un extremo en cada mano, palmas hacia delante. Codos fijos junto al cuerpo; sube las manos a los hombros y baja despacio frenando la banda.'],
  rosca_toalha: ['Sit or stand with one foot on the middle of a towel, holding both ends with the palms up. Curl up while the foot pushes down to resist, 3 s up and 3 s down. You set the effort: make the last reps hard.', 'Sentado ou em pé, com um pé no meio de uma toalha e segurando as duas pontas, palmas para cima. Suba as mãos enquanto o pé empurra para baixo, resistindo: 3 s subindo e 3 s descendo. Você controla a força: deixe as últimas repetições difíceis.', 'Sentado o de pie, con un pie en el centro de una toalla y sujetando los dos extremos, palmas hacia arriba. Sube las manos mientras el pie empuja hacia abajo, resistiendo: 3 s subiendo y 3 s bajando. Tú decides la fuerza: haz que las últimas repeticiones cuesten.'],
  face_pull_elastico: ['Band anchored at face height. Hold the ends with the palms down and step back until it is taut. Pull toward the face with the elbows high and wide, ending with the hands beside the ears and the shoulder blades squeezed.', 'Elástico preso na altura do rosto. Segure as pontas com as palmas para baixo e dê um passo para trás até esticar. Puxe em direção ao rosto com os cotovelos altos e abertos, terminando com as mãos ao lado das orelhas e as escápulas juntas.', 'Banda anclada a la altura de la cara. Sujeta los extremos con las palmas hacia abajo y da un paso atrás hasta tensarla. Tira hacia la cara con los codos altos y abiertos, terminando con las manos junto a las orejas y las escápulas juntas.'],
  elev_lateral_elastico: ['Stand on the band (with one foot or both), one end in each hand at your sides. Raise the arms out to the sides up to shoulder height, elbows slightly bent and leading, then lower slowly.', 'Pise no elástico (com um pé ou os dois), uma ponta em cada mão ao lado do corpo. Suba os braços para os lados até a altura dos ombros, cotovelos levemente dobrados indo na frente, e desça devagar.', 'Pisa la banda (con un pie o los dos), un extremo en cada mano a los lados. Sube los brazos hacia los lados hasta la altura de los hombros, codos un poco doblados y por delante, y baja despacio.'],
  agach_livre: ['Feet shoulder-width, toes turned out a little, arms forward for balance. Sit down and back with the heels on the floor and the knees following the toes; go as deep as you can with a flat back, then stand up.', 'Pés na largura dos ombros, pontas um pouco para fora, braços à frente para equilibrar. Sente para trás e para baixo com os calcanhares no chão e os joelhos seguindo a direção dos pés; desça o máximo que conseguir com as costas retas e suba.', 'Pies al ancho de los hombros, puntas un poco hacia fuera, brazos al frente para equilibrar. Siéntate hacia atrás y abajo con los talones en el suelo y las rodillas siguiendo los pies; baja todo lo que puedas con la espalda recta y sube.'],
  agach_salto: ['Squat until the thighs are about parallel to the floor, then jump as high as you can. Land softly on the balls of the feet, bending the knees to absorb, and flow into the next rep. End the set when the jumps get lower.', 'Agache até as coxas ficarem mais ou menos paralelas ao chão e salte o mais alto que puder. Aterrisse macio, na ponta dos pés, dobrando os joelhos para amortecer, e emende a próxima. Encerre a série quando os saltos começarem a baixar.', 'Agáchate hasta que los muslos queden más o menos paralelos al suelo y salta lo más alto que puedas. Aterriza suave, en la punta de los pies, doblando las rodillas para amortiguar, y enlaza la siguiente. Termina la serie cuando los saltos bajen.'],
  agach_mochila: ['Hug a loaded backpack against the chest (or wear it on the front). Feet shoulder-width, toes slightly out; sit down between the heels with the chest up and the heels down, then stand up.', 'Abrace a mochila com peso junto ao peito (ou vista-a na frente). Pés na largura dos ombros, pontas um pouco para fora; desça sentando entre os calcanhares, peito aberto e calcanhares no chão, e suba.', 'Abraza la mochila con peso contra el pecho (o póntela por delante). Pies al ancho de los hombros, puntas un poco hacia fuera; baja sentándote entre los talones, pecho arriba y talones en el suelo, y sube.'],
  afundo_reverso: ['Stand tall, take a long step back and lower the back knee toward the floor; the front shin stays close to vertical with the weight on the front heel. Push through the front foot to come back. Alternate legs, or do all the reps on one side first.', 'Em pé, dê um passo longo para trás e desça o joelho de trás em direção ao chão; a canela da frente fica quase vertical e o peso no calcanhar da frente. Empurre com o pé da frente para voltar. Alterne as pernas ou faça todas de um lado primeiro.', 'De pie, da un paso largo hacia atrás y baja la rodilla de atrás hacia el suelo; la espinilla delantera queda casi vertical y el peso en el talón de delante. Empuja con el pie de delante para volver. Alterna las piernas o haz todas de un lado primero.'],
  afundo_lateral: ['Feet wide apart, toes forward. Shift your weight to one side, bending that knee and pushing the hips back while the other leg stays straight; both heels stay down. Push back to the middle.', 'Pés bem afastados, pontas para a frente. Leve o peso para um lado dobrando aquele joelho e jogando o quadril para trás, com a outra perna esticada; os dois calcanhares no chão. Empurre de volta para o meio.', 'Pies muy separados, puntas hacia delante. Lleva el peso hacia un lado doblando esa rodilla y echando la cadera atrás, con la otra pierna estirada; los dos talones en el suelo. Empuja de vuelta al centro.'],
  bulgaro_cadeira: ['Top of the rear foot on a sturdy chair pushed against a wall, the front foot about a long step ahead. Lower straight down until the back knee nearly touches the floor, front knee over the foot, torso slightly forward. Hold onto something if balance is hard.', 'Peito do pé de trás apoiado numa cadeira firme encostada na parede, pé da frente cerca de um passo largo à frente. Desça reto até o joelho de trás quase tocar o chão, joelho da frente sobre o pé, tronco um pouco inclinado. Se o equilíbrio for difícil, segure em algo.', 'Empeine del pie trasero sobre una silla firme apoyada contra la pared, el pie delantero a un paso largo. Baja recto hasta que la rodilla de atrás casi toque el suelo, rodilla delantera sobre el pie, tronco un poco inclinado. Si el equilibrio cuesta, sujétate a algo.'],
  agach_parede: ['Back flat against a wall, slide down until the knees are at about 90°, feet under the knees at shoulder width. Hold without resting the hands on the thighs, breathing normally.', 'Costas apoiadas na parede, deslize até os joelhos ficarem a uns 90°, pés embaixo dos joelhos na largura dos ombros. Segure sem apoiar as mãos nas coxas, respirando normalmente.', 'Espalda apoyada en la pared, deslízate hasta que las rodillas queden a unos 90°, pies bajo las rodillas al ancho de los hombros. Aguanta sin apoyar las manos en los muslos, respirando con normalidad.'],
  sissy: ['Hold a wall or a door frame with one hand for balance. Rise onto the balls of the feet and lean back, letting the knees travel forward and down while the body stays straight from knees to head. Go only as low as the knees feel comfortable, then come back up.', 'Segure numa parede ou batente com uma mão, só para equilibrar. Fique na ponta dos pés e incline o corpo para trás, deixando os joelhos irem para a frente e para baixo, com o corpo reto dos joelhos à cabeça. Desça só até onde os joelhos ficarem confortáveis e suba.', 'Sujétate a una pared o al marco de una puerta con una mano, solo para equilibrarte. Ponte de puntillas e inclina el cuerpo hacia atrás, dejando que las rodillas vayan hacia delante y abajo, con el cuerpo recto de las rodillas a la cabeza. Baja solo hasta donde las rodillas estén cómodas y sube.'],
  ponte_unilateral: ['On your back, one foot flat near the glutes, the other leg straight up or bent toward the chest. Push through the heel to lift the hips until the body is straight from knee to shoulders, squeeze the glute for 1–2 s and lower slowly.', 'Deitado de costas, um pé no chão perto dos glúteos e a outra perna esticada para cima ou dobrada em direção ao peito. Empurre com o calcanhar para subir o quadril até o corpo ficar reto do joelho aos ombros, contraia o glúteo por 1–2 s e desça devagar.', 'Boca arriba, un pie apoyado cerca de los glúteos y la otra pierna estirada hacia arriba o doblada hacia el pecho. Empuja con el talón para subir la cadera hasta que el cuerpo quede recto de la rodilla a los hombros, aprieta el glúteo 1–2 s y baja despacio.'],
  stiff_corpo: ['Stand on one leg with the knee soft, a hand on a wall if needed. Hinge at the hip, sending the free leg back as the torso comes forward with a flat back, until the back of the thigh stretches; keep the hips level. Squeeze the glute to stand up.', 'Em pé numa perna, joelho levemente dobrado, uma mão na parede se precisar. Dobre o quadril levando a perna livre para trás enquanto o tronco vai à frente, costas retas, até sentir alongar a parte de trás da coxa; o quadril fica reto, sem girar. Contraia o glúteo para subir.', 'De pie sobre una pierna, rodilla un poco doblada, una mano en la pared si hace falta. Dobla la cadera llevando la pierna libre atrás mientras el tronco va al frente con la espalda recta, hasta sentir estirar la parte de atrás del muslo; la cadera queda recta, sin girar. Aprieta el glúteo para subir.'],
  flexora_toalha: ['On your back on a smooth floor, heels on a towel (or in socks), knees bent. Lift the hips into a bridge, slide the heels away until the legs are almost straight, then pull them back in, keeping the hips up. Harder: one leg.', 'Deitado de costas num piso liso, calcanhares sobre uma toalha (ou de meia), joelhos dobrados. Suba o quadril como numa ponte, deslize os calcanhares para longe até as pernas quase esticarem e puxe de volta, sem deixar o quadril cair. Mais difícil: uma perna só.', 'Boca arriba en un suelo liso, talones sobre una toalla (o con calcetines), rodillas dobladas. Sube la cadera como en un puente, desliza los talones hasta casi estirar las piernas y tira de vuelta, sin dejar caer la cadera. Más difícil: con una sola pierna.'],
  kb_swing: ['Feet a bit wider than the hips, kettlebell a step in front. Hike it back between the legs with a flat back, then snap the hips forward to swing it to chest height with straight arms: the power comes from the hips, not the arms. Let it fall back and hinge again.', 'Pés um pouco mais abertos que o quadril, kettlebell um passo à frente. Leve-o para trás entre as pernas com as costas retas e estenda o quadril com força para ele subir até a altura do peito com os braços esticados: a força vem do quadril, não dos braços. Deixe cair de volta e dobre o quadril de novo.', 'Pies un poco más abiertos que la cadera, kettlebell un paso por delante. Llévala atrás entre las piernas con la espalda recta y extiende la cadera con fuerza para que suba hasta el pecho con los brazos estirados: la fuerza sale de la cadera, no de los brazos. Déjala caer y vuelve a doblar la cadera.'],
  hollow: ['On your back, press the lower back into the floor. Lift the shoulders and legs a little off the floor, arms reaching past the head (or toward the feet, to make it easier). Hold the banana shape without the lower back lifting.', 'Deitado de costas, cole a lombar no chão. Tire os ombros e as pernas um pouco do chão, braços esticados para trás da cabeça (ou em direção aos pés, para facilitar). Segure a forma de "banana" sem a lombar sair do chão.', 'Boca arriba, pega la zona lumbar al suelo. Levanta un poco los hombros y las piernas, brazos estirados detrás de la cabeza (o hacia los pies, para facilitar). Aguanta la forma de "plátano" sin que la lumbar se despegue.'],
  escalador: ['High plank, hands under the shoulders, body straight. Drive one knee toward the chest, then switch legs quickly, keeping the hips low and the shoulders over the hands.', 'Prancha alta, mãos embaixo dos ombros, corpo reto. Leve um joelho em direção ao peito e troque de perna rapidamente, mantendo o quadril baixo e os ombros sobre as mãos.', 'Plancha alta, manos bajo los hombros, cuerpo recto. Lleva una rodilla hacia el pecho y cambia de pierna rápido, con la cadera baja y los hombros sobre las manos.'],
  abd_bicicleta: ['On your back, hands lightly beside the head, legs raised. Bring one elbow toward the opposite knee while the other leg stretches out, then switch, slowly, turning the chest rather than pulling the neck.', 'Deitado de costas, mãos leves ao lado da cabeça, pernas no ar. Leve um cotovelo em direção ao joelho oposto enquanto a outra perna estica e troque, devagar, girando o tronco em vez de puxar o pescoço.', 'Boca arriba, manos ligeras junto a la cabeza, piernas en el aire. Lleva un codo hacia la rodilla contraria mientras la otra pierna se estira y cambia, despacio, girando el tronco en vez de tirar del cuello.'],
  perdigueiro: ['On hands and knees, hands under the shoulders and knees under the hips, back flat. Reach one arm forward and the opposite leg back until both are in line with the body, hold 2 s without the hips turning, then return and switch.', 'De quatro apoios, mãos embaixo dos ombros e joelhos embaixo do quadril, costas retas. Estique um braço à frente e a perna oposta para trás até ficarem na linha do corpo, segure 2 s sem girar o quadril, volte e troque.', 'A cuatro patas, manos bajo los hombros y rodillas bajo la cadera, espalda recta. Estira un brazo al frente y la pierna contraria atrás hasta quedar en línea con el cuerpo, aguanta 2 s sin girar la cadera, vuelve y cambia.'],
});
Object.assign(STR, { pos_title: ['Hands and body position', 'Posição das mãos e do corpo', 'Posición de manos y cuerpo'] });
const pegadaHTML = id => (PEGADA[id] ? `<div class="pos"><p class="eyebrow">${t('pos_title')}</p><p class="small">${esc(L3(PEGADA[id]))}</p></div>` : '');
